import{_ as t,a as s,b as a,c as i,d as n,e as r,f as o,g as d}from"./chunks/weather-heating-meteored.DOiN_qir.js";import{_ as l,o as h,c as p,a3 as g}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Weather and Heating","description":"Install and configure the optional chart widget package.","frontmatter":{"title":"Weather and Heating","description":"Install and configure the optional chart widget package."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/weather-heating.md","filePath":"en/projects/grafik-visual-studio/weather-heating.md","lastUpdated":1792859421000}'),c={name:"en/projects/grafik-visual-studio/weather-heating.md"};function u(k,e,m,y,E,w){return h(),p("div",null,[...e[0]||(e[0]=[g('<h1 id="weather-and-heating" tabindex="-1">Weather and Heating <a class="header-anchor" href="#weather-and-heating" aria-label="Permalink to &quot;Weather and Heating&quot;">​</a></h1><p>Packages and helper tools are provided centrally at <a href="https://visualstudio.ugso-software.de/?lang=en" target="_blank" rel="noreferrer">visualstudio.ugso-software.de</a>. This open-source page provides descriptions and instructions; downloads are provided by the package catalog.</p><p><strong>Inspired by the ioBroker “Weather and Heating” widgets by <a href="https://github.com/rg-engineering/ioBroker.vis-2-widgets-weather-and-heating" target="_blank" rel="noreferrer">rg-engineering</a>.</strong> The Studio widgets are an independent implementation for Home Assistant.</p><p>From <strong>Studio 0.1.194</strong>, you can install <strong>Weather and Heating 1.7.0</strong>. It contains <strong>General Chart</strong>, <strong>Two Weeks Bar Chart</strong>, <strong>Weather Widget</strong>, <strong>Heating Rooms Overview</strong>, <strong>METEORED Weather Widget</strong>, <strong>Window Status Overview</strong>, <strong>Inform my landlord</strong> and <strong>General heating parameters</strong>. The functional reference is <a href="https://github.com/rg-engineering/ioBroker.vis-2-widgets-weather-and-heating" target="_blank" rel="noreferrer">ioBroker.vis-2-widgets-weather-and-heating</a>; Studio uses original renderers. Other weather/heating widgets and ioBroker-specific adapter bindings are not included yet.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Download <a href="https://visualstudio.ugso-software.de/?kind=widget&amp;lang=en" target="_blank" rel="noreferrer">ugso.weather-heating.wg</a>. Open <strong>Settings → Widget packages → Install local .wg / .wg.zip</strong> and select the file. After reloading, a separate set appears with an automatically assigned color. This browser remembers its color across removal and reinstallation. The 74 built-in widgets remain available.</p><h2 id="configure-the-chart" tabindex="-1">Configure the chart <a class="header-anchor" href="#configure-the-chart" aria-label="Permalink to &quot;Configure the chart&quot;">​</a></h2><p>An installed 1.0.0 through 1.6.0 package can be updated to 1.7.0 through the same import. Existing widgets and saved project values remain intact. Updates may only add widgets; changes to existing definitions and downgrades are rejected.</p><h2 id="general-heating-parameters" tabindex="-1">General heating parameters <a class="header-anchor" href="#general-heating-parameters" aria-label="Permalink to &quot;General heating parameters&quot;">​</a></h2><p>The widget displays eight rows: <strong>Heating period active</strong>, <strong>Public holiday today</strong>, <strong>Present</strong>, <strong>Party now</strong>, <strong>Guests present</strong>, <strong>Holiday at home</strong>, <strong>Vacation away</strong> and <strong>Fireplace mode</strong>. Under <strong>Heating parameter entities</strong>, assign an independent HA entity to each row. The optional chosen-room entity is displayed as text above the switches and is never modified. The original <code>heatingcontrol.0</code> instance is not required.</p><p>Available <code>input_boolean.*</code> and <code>switch.*</code> entities with <code>on</code>/<code>off</code> states are writable in runtime. Each action turns only the clicked entity on or off. Sensors, such as <code>binary_sensor.*</code>, are display-only. A pending command blocks that entity; failures use Studio&#39;s existing switch status. <strong>General → Read-only</strong> blocks all writes. <strong>Without card</strong> removes the outer card background.</p><p>Unbound runtime rows are disabled and marked <strong>Unbound</strong>. Missing or unavailable bound readings show <strong>Unknown</strong> with a striped switch. Preview values never replace live readings. The <strong>Preview</strong> checkboxes apply only in the unbound editor; the editor sends no commands.</p><p>All nine entity bindings, preview values, read-only and display options remain in project and widget exports. This widget groups your existing HA entities; it does not calculate heating schedules, holidays or presence and provides no heating controller of its own.</p><p><img src="'+t+'" alt="General heating parameters and entity bindings"></p><h2 id="inform-my-landlord" tabindex="-1">Inform my landlord <a class="header-anchor" href="#inform-my-landlord" aria-label="Permalink to &quot;Inform my landlord&quot;">​</a></h2><p>The widget provides <strong>Priority</strong> (Information, Important, Urgent), <strong>Message</strong> and <strong>Send</strong>. The editor is a preview. Runtime submits to Home Assistant only on deliberate sending. Empty messages and repeated clicks during a pending submission are blocked. Failure retains the message for retry; HA acceptance clears it. Acceptance does not confirm delivery.</p><p><strong>General</strong> provides <strong>Without card</strong>, <strong>Message type</strong>, <strong>HA notification action</strong>, <strong>Notification entity</strong> and <strong>Subject / message heading</strong>. Example: action <code>notify.send_message</code> with your specific entity <code>notify.landlord</code>. Alternatively, use a configured named action such as <code>notify.landlord_email</code>, leaving the entity field empty. The unspecified <code>notify.notify</code> action is rejected. Configure recipients, credentials and providers in HA, not in the widget. See <a href="https://www.home-assistant.io/integrations/notify/" target="_blank" rel="noreferrer">HA notifications</a>.</p><p>Email, WhatsApp, Signal, Pushbullet and Jira describe the configured channel. Selecting a type does not install a provider or automatically change the HA destination. Your HA action replaces the original ioBroker <code>email.0</code> instance. The original currently implements email sending only; Studio uses the same HA contract for all configured channels.</p><p>The heading and priority are prepended as message text, for example <code>Inform my landlord</code> and <code>[urgent]</code>. Priority is not a provider-specific delivery or alarm level. Limits: 10,000 message characters and 200 heading characters. Drafts survive HA state redraws but remain only in the current form: page changes or reloads discard them. Project/widget exports contain configuration, not entered messages.</p><p><img src="'+s+`" alt="Message form and HA destination configuration in the editor"></p><h2 id="window-status-overview" tabindex="-1">Window Status Overview <a class="header-anchor" href="#window-status-overview" aria-label="Permalink to &quot;Window Status Overview&quot;">​</a></h2><p>Under <strong>Window list</strong>, select an HA entity and optional attribute providing a JSON array. The original data point is named <code>WindowStatesHtmlTableVis2</code>, but contains JSON. Without an entity binding, the widget uses its editable preview:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Living room&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sinceText&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;since&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;changed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;03.10.2026 12:30&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;isOpen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Kitchen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sinceText&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;since&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;changed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;03.10.2026 11:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;isOpen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>isOpen</code> accepts Boolean values, 1/0 and the strings <code>true</code>/<code>false</code>, <code>on</code>/<code>off</code>, <code>open</code>/<code>closed</code>. If the status is missing, the widget recognizes the legacy icon names <code>fts_window_1w_open.svg</code> and <code>fts_window_1w.svg</code> without loading image files. Otherwise it shows <strong>Unknown</strong>. Room and change strings are plain text, not HTML. Limits: 200,000 JSON characters, 500 rooms and 512 characters per text field.</p><p><strong>Open rooms: entity</strong> and an optional attribute provide a separate non-negative integer count of rooms with open windows. Without this binding, the count is derived only from a non-empty list with fully known states. Missing bound data never uses preview data; an unknown count is explicitly displayed.</p><p><strong>Colors</strong> provides headline, status line, open/closed room name, open/closed last change and room background colors. Open defaults to red, closed to green, and its change time to blue. Assignments follow the field names; the reversed assignments in the original are not copied. A dedicated background color replaces the ioBroker theme value <code>background.paper</code>. <strong>General → Without card</strong> removes the outer card background. Settings are retained in project and widget exports.</p><p>Your HA entity must already provide the JSON list; this widget does not aggregate individual window sensors or write HA states. No <code>heatingcontrol</code> adapter is required.</p><p><img src="`+a+`" alt="Window Status Overview with open and closed rooms"></p><p><strong>General</strong> provides a headline, series count (1–10), legend and display without a card. The first series can use the main entity. Each <strong>Data [N]</strong> group provides its own entity, optional attribute, preview JSON, X/Y keys, name, unit, color, line/bar type, left/right axis and difference calculation. A bound series reads only its entity state or attribute. Missing live data never falls back to preview JSON. The widget does not write HA states.</p><p>Example preview JSON or HA attribute:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T08:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T09:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T10:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Default keys are <code>x</code> and <code>value</code>; custom keys and <code>[x,y]</code> pairs are supported. <strong>Time</strong> expects ISO dates or Unix milliseconds. <strong>Category</strong> displays text, such as year labels. Time points are sorted before difference calculation. Missing readings break lines and difference sequences; the first difference has no predecessor. Left/right axes scale independently.</p><p><strong>X axis</strong> defaults to <code>ddd HH:mm</code>. Supported tokens: <code>YYYY</code>, <code>MM</code>, <code>DD</code>, <code>ddd</code>, <code>HH</code>, <code>mm</code>, <code>ss</code>. Colors are under <strong>WIDGET → Chart CSS</strong>. Input arrays may contain up to 20,000 rows; large series are reduced to at most 500 points each. The widget does not fetch HA history: its entity must already provide the data array.</p><p><img src="`+i+'" alt="Installed set and chart preview"></p><h2 id="two-weeks-bar-chart" tabindex="-1">Two Weeks Bar Chart <a class="header-anchor" href="#two-weeks-bar-chart" aria-label="Permalink to &quot;Two Weeks Bar Chart&quot;">​</a></h2><p><strong>Current week</strong> and <strong>Previous week</strong> each provide seven HA entity bindings, Monday through Sunday, plus editable preview values. Daily pairs appear side by side. The widget does not calculate weekly history or shift values at the start of a new week: its sensors must already provide the corresponding daily readings.</p><p><strong>Show weekly values</strong> matches the original “Visible” option: disabled displays only preview values; enabled reads only the fourteen daily entities. Unbound, unavailable or non-numeric live readings have no bars. Zero is valid. Overall widget visibility remains controlled under <strong>Visibility</strong>.</p><p><strong>General</strong> provides a headline and color, legend text color, unit, week colors, axis label color, left/right Y axis, 0–5 decimal places, legend and <strong>Without card</strong>. <strong>X axis</strong> has a separate color. Units and formatted values appear in the legend and bar tooltips; weekdays follow the app language. Configured colors are used as entered.</p><p><img src="'+n+'" alt="Two Weeks Bar Chart in the installed set"></p><h2 id="weather-widget" tabindex="-1">Weather Widget <a class="header-anchor" href="#weather-widget" aria-label="Permalink to &quot;Weather Widget&quot;">​</a></h2><p><strong>Data source</strong> offers <code>home-assistant</code>, <code>json</code> and <code>individual</code>. <strong>Data structure</strong> selects five daily values (<code>daily</code>) or up to 24 hourly values (<code>hourly</code>). These sources replace ioBroker instance/OID selection with HA bindings.</p><p>With <code>home-assistant</code>, choose a <code>weather.*</code> entity. Studio&#39;s server reads forecasts through <a href="https://www.home-assistant.io/integrations/weather/" target="_blank" rel="noreferrer">weather.get_forecasts</a>. Successful responses are cached for five minutes; failures retry no sooner than one minute later. The weather integration must support the selected forecast type. Temperature and precipitation units come from its attributes. A real HA request requires the running add-on/Supervisor connection.</p><p>With <code>json</code>, the widget reads the selected <strong>Forecast attribute (JSON)</strong>; an empty attribute reads the entity state. Supply an array, for example:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;datetime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T12:00:00Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;temperature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;templow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;precipitation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cloud_coverage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;precipitation_probability&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>With <code>individual</code>, bind <strong>Daily dates [1–5]</strong> or <strong>Timestamps [1–24]</strong>, plus their corresponding temperature, rain, cloud and probability values, to individual sensors. Dates may be ISO strings or Unix milliseconds. Daily views use only the first five bindings in each value group. Invalid timestamps are omitted, missing values break lines, and zero is valid. Without a bound weather/JSON entity, the first two sources show editable preview data. Missing live data never falls back to preview values.</p><p><strong>Temperature</strong>, <strong>Rain</strong>, <strong>Clouds</strong> and <strong>Rain probability</strong> can be enabled individually. Each group has colors and a left/right value axis; rain uses bars. <strong>Show in separate chart</strong> creates its own panel. Incompatible units on the same axis automatically split into separate panels. <strong>Sun or clouds</strong> displays cloud coverage or its complement as a percentage, not sunshine hours. Missing provider values are never inferred from weather conditions. Name, optional location entity, legend, colors, X date format, size and <strong>Without card</strong> are configurable.</p><p><img src="'+r+'" alt="Weather Widget with temperature and rain"></p><h2 id="heating-rooms-overview" tabindex="-1">Heating Rooms Overview <a class="header-anchor" href="#heating-rooms-overview" aria-label="Permalink to &quot;Heating Rooms Overview&quot;">​</a></h2><p>From <strong>0.1.190</strong>, this widget displays an existing HTML room table, corresponding to the original <code>RoomStatesHtmlTable</code> data point. Under <strong>Room table</strong>, select an HA entity and optionally a <strong>Table attribute</strong>. An empty attribute reads the entity state. A bound widget uses only live data; missing or unavailable values show <strong>No room table available</strong>. Without an entity binding, edit <strong>Preview room table (HTML)</strong> directly or through the HTML editor.</p><p>The widget does not generate room data/heating profiles or control thermostats. No ioBroker instance such as <code>heatingcontrol.0</code> is required; the chosen HA source must already provide an HTML table string. Long HTML content generally belongs in an attribute rather than the state.</p><p><strong>General → Without card</strong>, <strong>Colors → Headline color</strong>, size and shared CSS settings are available. Tables, text formatting, cell spans and selected colors/spacing are preserved. Scripts, event handlers, forms, embeds and external resources are removed. Input is limited to 200,000 characters; rendering is limited to 5,000 nodes and 40 nesting levels. Large tables scroll within the widget. All settings remain in widget/project exports.</p><p><img src="'+o+'" alt="Heating Rooms Overview with preview table"></p><h2 id="meteored-weather-widget" tabindex="-1">METEORED Weather Widget <a class="header-anchor" href="#meteored-weather-widget" aria-label="Permalink to &quot;METEORED Weather Widget&quot;">​</a></h2><p>From <strong>0.1.191</strong>, <strong>General</strong> provides <strong>Without card</strong>, <strong>Meteored widget ID</strong> and <strong>Enable reload</strong>. Create your widget at <a href="https://www.daswetter.com/widget/" target="_blank" rel="noreferrer">Meteored / daswetter.com</a> and enter only its ID, not full HTML code or a URL. IDs accept 1–128 letters, digits, underscores or hyphens. Allow the domain you actually use to open the runtime in the provider configuration.</p><p>The runtime loads the official <code>https://api.meteored.com/widget/loader/ID</code> loader in a separate frame. Internet access and valid provider settings are required. <strong>Enable reload</strong> is on by default and reloads once per hour. Disabling it stops the timer; ID changes and widget removal clean up the old timer. Ordinary runtime redraws do not restart the frame or timer. The editor shows a configuration preview; empty or invalid IDs load nothing.</p><p>The frame uses <code>sandbox=&quot;allow-scripts&quot;</code>; the loader page receives the same sandbox through its HTTP header. Meteored code therefore runs without access to Studio&#39;s DOM. No HA entity is needed; location, language and appearance come from your Meteored configuration. All three options, size and CSS remain in exports. Fully verifying the provider display requires your real widget ID and allowed domain.</p><p><img src="'+d+'" alt="METEORED configuration in the editor"></p><p>The reproducible builder and validated manifest are in the <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/weather-heating" target="_blank" rel="noreferrer">source repository</a>. The <a href="./widget-packages">package contract</a> describes interface 0.2.</p>',58)])])}const C=l(c,[["render",u]]);export{f as __pageData,C as default};
